/// <summary>
/// UPSPricingAttribute of table <c>InventTableModule</c> field SuppItemGroupId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableModuleSuppItemGroupId extends UPSPricingAttributeInventTableModule implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTableModule, SuppItemGroupId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);

    SuppItemGroup  suppItemGroup;

    while select GroupId from suppItemGroup
        where suppItemGroup.Module == ModuleInventCustVend::Invent
    {
        if (!ret.in(suppItemGroup.GroupId))
        {
            ret.add(suppItemGroup.GroupId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTableModule, SuppItemGroupId));
    qbr.value(queryValue(_value));
}
